function sendRandom(dial) {
  var currentUnixTime = Date.parse(new Date()) / 1000;
  var unixTimeStamp = currentUnixTime.toString();
  var randomNum = Math.floor(Math.random() * 1000000);
  console.log(randomNum);
  var dialS = dial;
  var signsms = this.hex_sha256("appkey=9af7c74b29d7d97aec74d151c240f943&random=" + randomNum + "&time=" + unixTimeStamp + "&mobile=" + dialS);
  console.log(signsms);
  uni.request({
    url: 'https://yun.tim.qq.com/v5/tlssmssvr/sendsms?sdkappid=1400232308&random=' + randomNum,
    method: "POST",
    data: {
      "ext": "",
      "extend": "",
      "params": [randomNum],
      "sig": signsms,
      "sign": 'Squirrel Town',
      "tel": {
        "mobile": dialS,
        "nationcode": '1' },

      "time": currentUnixTime,
      "tpl_id": 376617 },

    success: function success(res) {
      console.log(res);
    } });

}

function formatTime(date) {
  var year = date.getFullYear();
  var month = date.getMonth() + 1;
  var day = date.getDate();
  return [month, day, year].map(formatNumber).join('/');
}

function formatTime2(date) {
  var year = date.getFullYear();
  var month = date.getMonth() + 1;
  var day = date.getDate();
  return {
    year: year,
    month: month,
    day: day };

}

function formatNumber(n) {
  n = n.toString();
  return n[1] ? n : '0' + n;
}

function lvlFromExp(exp) {
  var remExp = exp;
  var nextLvl = 1000;
  var resLvl = 1;

  while (remExp >= nextLvl) {
    remExp -= nextLvl;
    nextLvl = nextLvl * 1.5;
    resLvl++;
  }

  return {
    resLvl: resLvl,
    expToNext: nextLvl,
    remExp: remExp };

}

function cloudRemove(strList) {
  wx.cloud.deleteFile({
    fileList: strList,
    success: function success(res) {
      // handle success
      console.log(res);
    },
    fail: function fail(err) {
      // handle error
      console.log("failed");
      console.log(res);
    } });

}

function removePost(commuListId, tmpXiaoneiId, imgs) {
  var that = this;
  wx.cloud.callFunction({
    name: 'deleteWithId',
    data: {
      dbname: 'xiaonei',
      id: tmpXiaoneiId },

    success: function success(res) {
      wx.cloud.callFunction({
        name: 'deleteWithId',
        data: {
          dbname: 'commuList',
          id: commuListId },

        success: function success(res) {
          console.log("Succc");
          that.cloudRemove(imgs);
        },
        fail: function fail(res) {
          console.log("disanceng");
          console.log(res);
        } });

    },
    fail: function fail(res) {
      console.log(res);
    } });

}

function giveExp(amount) {
  uni.request({
    url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/getuser',
    method: 'POST',
    data: {
      openId: getApp().globalData.openId },

    success: function success(res) {
      console.log(res);
      if (res.data.length == 0) {
        wx.cloud.callFunction({
          name: 'applyExp',
          data: {
            mode: 2,
            amount: amount,
            openId: getApp().globalData.openId },

          success: function success(res) {
            console.log("added");
          },
          fail: function fail(res) {
            console.log("failed to add");
            console.log(res);
          } });

      } else {
        uni.request({
          url: 'https://lej4kht0ig.execute-api.us-east-2.amazonaws.com/CLF/applyexp',
          method: 'POST',
          data: {
            mode: 1,
            amount: amount,
            openId: getApp().globalData.openId },

          success: function success(res) {
            console.log("updated");
          },
          fail: function fail(res) {
            console.log("failed to update");
            console.log(res);
          } });

      }
    } });

} //pay with paypal, return a redirect url to paypal experience

/*
* item format:
*"items": [
              {
                "name": "hat",
                "description": "Brown hat.",
                "quantity": "5",
                "price": "5",
                "tax": "0.01",
                "sku": "1",
                "currency": "USD"
              },

* shipping address example:
"shipping_address": {
              "recipient_name": "boss Zhao",
              "line1": "645 jsway ave",
              "line2": "???",
              "city": "Columbus",
              "country_code": "US",
              "postal_code": "43214",
              "phone": "011862212345678",
              "state": "OH"
            }
*/


function pplPay(accToken, itemList, shipping, discount, invoicNum) {
  //access token
  var tkn = 'Bearer ' + accToken; //total

  var subT = 0.00;
  var total = 0.00;
  var totalTax = 0.00; //

  for (var i = 0; i < itemList.length; i++) {
    var quanti = parseFloat(itemList[i].quantity).toFixed(0);
    var price = parseFloat(itemList[i].price).toFixed(2);
    var tax = parseFloat(itemList[i].price).toFixed(2);
    subT += quanti * price;
    totalTax += tax;
  }

  total = subT + parseFloat(shipping).toFixed(0);
  wx.request({
    //test link, change later
    url: 'https://api.sandbox.paypal.com/v1/payments/payment',
    header: {
      'Content-Type': 'application/json',
      'Authorization': tkn },

    method: "POST",
    data: {
      "intent": "sale",
      "payer": {
        "payment_method": "paypal" },

      "transactions": [{
        "amount": {
          "total": total.toString(),
          "currency": "USD",
          "details": {
            "subtotal": subtotal.toString(),
            "tax": totalTax.toString(),
            "shipping": shipping.toString(),
            "discount": discount.toString() } },


        "description": "测试的松鼠小镇paypal支付.",
        //what is this
        "custom": "EBAY_EMS_90048630024435",
        "invoice_number": invoicNum.toString(),
        "payment_options": {
          "allowed_payment_method": "INSTANT_FUNDING_SOURCE" },

        //what is this
        "soft_descriptor": "ECHI5786786",
        "item_list": {
          "items": itemList } }],


      "note_to_payer": "Contact us for any questions on your order.",
      "redirect_urls": {
        //change later
        "return_url": "https://example.com/return",
        "cancel_url": "https://example.com/cancel" } },


    success: function success(res) {
      console.log(res);
      console.log(res.data.links[1].href);
      app.globalData.payLink = res.data.links[1].href; //return res.data.links[1].href;

      wx.navigateTo({
        url: '../testPage/testThird' });

    } });

}
